- [ ] **Step 3: The base and the singletons**

`streamdeck/src/actions/base.ts`:

```ts
import streamDeck, { SingletonAction, type KeyAction, type WillAppearEvent, type WillDisappearEvent } from "@elgato/streamdeck";
import { faceImage } from "../face.ts";
import type { DeckState, Face } from "../state.ts";
import { store, wire, ensureConnected } from "../plugin.ts";

/**
 * Whether the plugin should be holding its socket.
 *
 * Configuration, not visibility. `willAppear` fires only for the visible
 * page of the active profile, and a streamer whose keys live in the
 * Runlog profile would otherwise have no socket while that profile was
 * in the background — so the plugin could never learn a run had started,
 * and could never switch to the profile. Visible keys decide what is
 * drawn; this decides whether anyone is listening.
 */
export function shouldConnect(x: { session: boolean; configured: boolean; visible: number }): boolean {
  return x.session && x.configured;
}

export abstract class RunlogAction<S extends object = object> extends SingletonAction<S> {
  private unsubscribe: (() => void) | null = null;

  abstract face(state: DeckState, settings: S, now: number): Face;

  override async onWillAppear(ev: WillAppearEvent<S>): Promise<void> {
    await streamDeck.settings.setGlobalSettings({ ...(await streamDeck.settings.getGlobalSettings()), configured: true });
    ensureConnected();
    this.unsubscribe ??= store.subscribe(() => this.redrawAll());
    await this.draw(ev.action as KeyAction<S>, ev.payload.settings);
  }

  override onWillDisappear(_ev: WillDisappearEvent<S>): void {
    if ([...this.actions].length === 0) {
      this.unsubscribe?.();
      this.unsubscribe = null;
    }
  }

  protected async draw(action: KeyAction<S>, settings: S): Promise<void> {
    const face = this.face(store.state, settings, Date.now());
    if (action.isKey()) {
      await action.setImage(faceImage(face));
      await action.setTitle("");
    }
    if (action.isDial()) await action.setFeedback({ title: face.when ?? "", value: face.title });
  }

  private redrawAll(): void {
    for (const a of this.actions) void a.getSettings().then((s) => this.draw(a as KeyAction<S>, s));
  }

  /** A press, with the flash the server's answer will turn into. */
  protected async send(action: KeyAction<S>, p: Parameters<typeof wire.press>[0]): Promise<void> {
    const ref = wire.press(p);
    if (!ref) {
      await action.showAlert();
      return;
    }
    const off = store.subscribe((s) => {
      if (s.flash?.ref !== ref) return;
      off();
      void (s.flash.ok ? action.showOk() : action.showAlert());
    });
  }
}
```

`plugin.ts` becomes:

```ts
import streamDeck from "@elgato/streamdeck";
import { makeStore } from "./store.ts";
import { openWire } from "./socket.ts";
import { loadSession, signIn, type Account } from "./session.ts";
import { shouldConnect } from "./actions/base.ts";
import { Next } from "./actions/next.ts";
import { Press } from "./actions/press.ts";
import { Undo } from "./actions/undo.ts";
import { Run } from "./actions/run.ts";
import { Metric } from "./actions/metric.ts";

export const account: Account = { apiBase: process.env["RUNLOG_API"] ?? "https://runlog.scrthq.com" };
export const store = makeStore();
export const wire = openWire(account, store);
let connected = false;

/** Called on every appear and after every sign-in; connects at most once. */
export function ensureConnected(): void {
  void (async () => {
    const session = loadSession() !== null;
    const g = await streamDeck.settings.getGlobalSettings<{ configured?: boolean; pinned?: string | null }>();
    store.dispatch({ t: "session", state: session ? "ok" : "none" });
    if (g.pinned !== undefined) store.dispatch({ t: "pin", id: g.pinned });
    if (!connected && shouldConnect({ session, configured: g.configured === true, visible: 0 })) {
      connected = true;
      wire.connect();
    }
  })();
}

streamDeck.ui.onSendToPlugin<{ t: string }>(async (ev) => {
  if (ev.payload.t !== "signin") return;
  await signIn(
    account,
    (line) => {
      const code = /([A-Z0-9]{4}-[A-Z0-9]{4})/.exec(line)?.[1];
      const url = /https?:\/\/\S+/.exec(line)?.[0];
      if (code && url) void streamDeck.ui.sendToPropertyInspector({ t: "code", code, url });
    },
    () => {},
  );
  void streamDeck.ui.sendToPropertyInspector({ t: "who", name: "you" });
  ensureConnected();
});

setInterval(() => store.dispatch({ t: "tick" }), 1000);

for (const a of [new Next(), new Press(), new Undo(), new Run(), new Metric()]) streamDeck.actions.registerAction(a);
streamDeck.connect();
ensureConnected();
```

- [ ] **Step 4: The five actions**

```ts
// next.ts
@action({ UUID: "com.scrthq.runlog.next" })
export class Next extends RunlogAction {
  face(state: DeckState) { return nextFace(state); }
  override async onKeyDown(ev: KeyDownEvent): Promise<void> { await this.send(ev.action, { press: "primary" }); }
  override async onTouchTap(ev: TouchTapEvent): Promise<void> { await this.send(ev.action as never, { press: "primary" }); }
}

// press.ts — settings: { target: PressTarget }
@action({ UUID: "com.scrthq.runlog.press" })
export class Press extends RunlogAction<{ target?: PressTarget }> {
  face(state: DeckState, s: { target?: PressTarget }) { return s.target ? pressFace(state, s.target) : { title: "Set up", tone: "dim" }; }
  override async onKeyDown(ev: KeyDownEvent<{ target?: PressTarget }>): Promise<void> {
    const t = ev.payload.settings.target;
    if (!t) return void ev.action.showAlert();
    if (t.kind === "roll") await this.send(ev.action, { press: "primary" });
    else if (t.kind === "move") await this.send(ev.action, { press: "move", move: t.id });
    else await this.send(ev.action, { press: "answer", answer: { [t.preset === "declareSubject" ? "subject" : t.preset]: t.value } });
  }
  override async onPropertyInspectorDidAppear(): Promise<void> {
    const offer = store.state.snapshot?.offer;
    await streamDeck.ui.sendToPropertyInspector({ t: "offer", moves: offer?.moves ?? [], presets: offer?.presets ?? [] });
  }
}

// undo.ts
@action({ UUID: "com.scrthq.runlog.undo" })
export class Undo extends RunlogAction {
  face(state: DeckState) { return undoFace(state); }
  override async onKeyDown(ev: KeyDownEvent): Promise<void> { await this.send(ev.action, { press: "undo" }); }
}

// metric.ts — settings: { field: MetricField }
@action({ UUID: "com.scrthq.runlog.metric" })
export class Metric extends RunlogAction<{ field?: MetricField }> {
  face(state: DeckState, s: { field?: MetricField }, now: number) { return metricFace(state, s.field ?? "score", now); }
}
```

